        <p>元旦同样是经验丰富的猎手，她吼一声催促幼虎们赶紧远离这里，也顾不上看它们散开没有，趁着棕熊两只前掌都被咬住，当机立断从背后扑上来，狠狠撕咬着棕熊的后颈。</p>
